# Test hypothesis: 
# 1. Find bands of consecutive non-background rows
# 2. For each band, find dominant non-background color
# 3. Create stripes of that color at col range where that color appears

def find_bands(grid):
    """Find bands of consecutive rows with non-background activity"""
    # Background seems to be the most common value in border rows
    border_vals = []
    for r in [0, len(grid)-1]:
        for c in range(len(grid[0])):
            border_vals.append(grid[r][c])
            if len(grid[r]) > 1:
                border_vals.append(grid[r][c])
    border_vals = border_vals[:20]  # First 20 border values
    bg_count = max(set(border_vals), key=border_vals.count)

    bands = []
    current_band = None
    for r in range(len(grid)):
        has_activity = any(grid[r][c] != bg_count for c in range(len(grid[0])))
        if has_activity:
            if current_band is None:
                current_band = r
        else:
            if current_band is not None:
                bands.append((current_band, r-1))
                current_band = None
    if current_band is not None:
        bands.append((current_band, len(grid)-1))
    return bands, bg_count

# Test on demo
demo_bands, demo_bg = find_bands(inp1)
print(f"Demo input: background = {demo_bg}")
print(f"Demo bands: {demo_bands}")

# For each band, find stripe
def determine_band_stripe(grid, band_start, band_end, bg_color):
    """Determine the stripe for this band"""
    # Find all activations in this band
    active_cols = []
    for r in range(band_start, band_end + 1):
        for c in range(len(grid[0])):
            if grid[r][c] != bg_color:
                active_cols.append(c)

    if not active_cols:
        return None, set()

    # Find the dominant non-bg color
    color_counts = {}
    for r in range(band_start, band_end + 1):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v != bg_color:
                color_counts[v] = color_counts.get(v, 0) + 1

    dominant_color = max(color_counts, key=color_counts.get)

    # Strip of dominant color at where dominant color appears
    stripe_cols = []
    for r in range(band_start, band_end + 1):
        for c in range(len(grid[0])):
            if grid[r][c] == dominant_color:
                stripe_cols.append(c)

    if stripe_cols:
        min_c, max_c = min(stripe_cols), max(stripe_cols)
        return dominant_color, set(range(min_c, max_c + 1))

    # If no dominant color found, use overall most active range
    active_range = range(min(active_cols), max(active_cols) + 1)
    return 6, active_range  # Default to 6 for now

