def detect_bands(grid, bg):
    """Detect bands of consecutive rows with non-bg activity, separately by row"""
    # For each row, detect if it has "core" activity (not noise)
    # Core activity = rows where a specific band color appears consistently

    rows_activity = []
    for r in range(len(grid)):
        active_cols = [(c, grid[r][c]) for c in range(len(grid[0])) if grid[r][c] != bg]
        rows_activity.append(active_cols)

    # Find bands: consecutive rows where the same color appears
    bands = []
    current_band_color = None
    current_band_rows = []

    for r, activity in enumerate(rows_activity):
        if not activity:
            if current_band_rows:
                bands.append((current_band_color, current_band_rows[:]))
                current_band_rows = []
            current_band_color = None
            continue

        # Check if this activity matches current band's color pattern
        common_color = None
        for c, v in activity:
            if common_color is None:
                common_color = v
            elif v != common_color:
                common_color = None
                break

        if common_color is not None and common_color == current_band_color:
            current_band_rows.append(r)
        else:
            if current_band_rows:
                bands.append((current_band_color, current_band_rows[:], current_band_color))
            current_band_color = common_color
            current_band_rows = [r]

    if current_band_rows:
        bands.append((current_band_color, current_band_rows[:], current_band_color))

    return bands

